B.Ro=new A.eL(2,"Comment te sens-tu ? Le je\xfbne vient de commencer.","Morse : Les premi\xe8res heures sont la transition. Le syst\xe8me lymphatique commence \xe0 se d\xe9sencombrer.","\ud83d\udca7",B.hb)
B.Rg=new A.eL(6,"Tu es \xe0 6h ! As-tu bu suffisamment d'eau ?","Morse : L'hydratation est la cl\xe9 de la filtration r\xe9nale. Eau de source ou eau distill\xe9e.","\ud83d\udeb0",B.hb)
B.R9=new A.eL(12,"\ud83d\udd25 Tu entres en c\xe9tose ! Comment \xe7a va ?","Morse : La c\xe9tose aide \xe0 dissoudre les acides stock\xe9s dans les tissus interstitiels. Les surr\xe9nales s'activent.","\ud83d\udd25",B.hc)
B.R7=new A.eL(18,"18h de je\xfbne ! Bravo. Des inconforts ?","Morse : Si tu as mal \xe0 la t\xeate, c'est normal \u2014 le corps \xe9limine des toxines. Repos et hydratation.","\ud83d\udcaa",B.hc)
B.Rl=new A.eL(24,"\ud83c\udf89 24h ! L'autophagie s'active. Comment te sens-tu ?","Morse : Nettoyage lymphatique profond. V\xe9rifie ton urine \u2014 la filtration devrait \xeatre visible.","\u267b\ufe0f",B.dM)
B.Re=new A.eL(36,"36h de je\xfbne. Tu es un guerrier. Ton corps ?","Morse : Les cellules se r\xe9g\xe9n\xe8rent. Les surr\xe9nales et les reins travaillent \xe0 plein r\xe9gime.","\ud83e\uddec",B.dM)
B.R6=new A.eL(48,"48h ! R\xe9g\xe9n\xe9ration cellulaire profonde. \xc9coute ton corps.","Morse : Les cellules souches s'activent. Le syst\xe8me immunitaire se reconstruit. Tu es en territoire sacr\xe9.","\ud83c\udf1f",B.dM)
B.a2e=s([B.Ro,B.Rg,B.R9,B.R7,B.Rl,B.Re,B.R6],t.fc)
B.aG3=new A.Cf("Scientifique",null)
B.aG2=new A.Cf("Vitalit\xe9",null)
