B.a2h=s(['"L\'homme est un moteur \xe0 air-gaz. La respiration correcte nourrit chaque cellule." \u2014 Ehret',"\"L'obstruction diminue quand l'oxyg\xe8ne circule. V = P \u2212 O.\" \u2014 Ehret",'"Respirez profond\xe9ment en plein air \u2014 c\'est le premier rem\xe8de." \u2014 Ehret'],t.s)
B.avn=new A.ah("\ud83c\udf3f Ehret : \xab La vie est une trag\xe9die de la nutrition. Presque tout ce que nous mangeons produit du mucus. \xbb",B.dS,"Arnold Ehret",B.o,null)
B.avu=new A.ah("\ud83d\udd2c Le r\xe9gime sans mucus d'Ehret repose sur un principe simple : les fruits et l\xe9gumes crus forment la base de toute gu\xe9rison.",B.a3,"Arnold Ehret",B.o,null)
B.avL=new A.ah("\u2697\ufe0f Ehret appelait le corps humain une \xab machine pneumatique \xbb \u2014 elle fonctionne \xe0 l'air et au soleil, pas \xe0 la viande.",B.bq,"Arnold Ehret",B.o,null)
B.avp=new A.ah("\ud83e\uddf9 \xab Chaque maladie, sans exception, est une crise de nettoyage. \xbb \u2014 Arnold Ehret. Les sympt\xf4mes sont de la gu\xe9rison.",B.cq,"Arnold Ehret",B.o,null)
B.aw4=new A.ah("\ud83c\udf4e Ehret classait les fruits comme les aliments les plus proches du soleil. Une transition par les fruits est sa base de protocole.",B.bj,"Arnold Ehret",B.o,null)
B.dr=new A.ml(3,"scared")
B.avb=new A.ah("\u26a0\ufe0f Ehret avertit : en phase de transition, la d\xe9tox peut sembler une aggravation. Pers\xe9v\xe9rez, c'est de la gu\xe9rison.",B.dr,"Arnold Ehret",B.o,null)
B.awE=new A.ah("\ud83c\udf3e Ehret tol\xe9rait les c\xe9r\xe9ales compl\xe8tes en phase de transition uniquement. Pas \xe0 long terme. L'amidon est du \xab colle \xbb digestive.",B.aE,"Arnold Ehret",B.o,null)
B.avP=new A.ah("\u2600\ufe0f Le je\xfbne rationnel selon Ehret : commencer doucement, augmenter progressivement. Jamais brutal pour un d\xe9butant.",B.a3,"Arnold Ehret",B.o,null)
B.ax0=new A.ah("\ud83d\udca8 \xab L'air et les fruits sont la nourriture de la vie. \xbb Ehret pratiquait des p\xe9riodes de respiration profonde en for\xeat.",B.br,"Arnold Ehret",B.o,null)
B.awi=new A.ah("\ud83d\udcd0 V = P \u2212 O. Vitalit\xe9 = Puissance \u2212 Obstruction. Manger moins peut donner PLUS d'\xe9nergie. C'est la cl\xe9 d'Ehret.",B.bq,"Arnold Ehret",B.o,null)
B.awU=new A.ah("\ud83d\udc45 Ehret : je\xfbne 24h puis examine ta langue. Enduit blanc = mucus qui sort. C'est le miroir de ta sant\xe9 interne.",B.cq,"Arnold Ehret",B.o,null)
B.aw0=new A.ah("\ud83e\udec1 Ehret voyait le corps comme une machine \xe0 air, pas \xe0 prot\xe9ines. L'oxyg\xe8ne et les fruits sont les vrais carburants.",B.a3,"Arnold Ehret",B.o,null)
B.awP=new A.ah("\ud83e\uddf9 Ehret a prouv\xe9 que l'humain moyen porte 2-5 kg de mati\xe8re non \xe9limin\xe9e dans les intestins. Le nettoyage est essentiel.",B.dr,"Arnold Ehret",B.o,null)
B.avB=new A.ah("\u26a1 \xab L'homme sain ne se fatigue pas \u2014 il est mouvement perp\xe9tuel. \xbb La fatigue vient de l'obstruction, pas du manque de nourriture.",B.br,"Arnold Ehret",B.o,null)
B.ax3=new A.ah("\ud83c\udf7d\ufe0f Mono-eating : un seul type d'aliment par repas est l'id\xe9al. Oranges seules, ou raisins seuls \u2014 digestion parfaite.",B.bj,"Arnold Ehret",B.o,null)
B.awT=new A.ah("\ud83d\udd78\ufe0f \xab Toute maladie est caus\xe9e par l'obstruction des vaisseaux capillaires par le mucus. \xbb \u2014 Arnold Ehret",B.dS,"Arnold Ehret",B.o,null)
B.awM=new A.ah("\ud83c\udf47 \xab Le r\xe9gime de fruits est le r\xe9gime du paradis \u2014 c'est le seul pour l'\xeatre humain. \xbb \u2014 Arnold Ehret",B.bj,"Arnold Ehret",B.o,null)
B.avX=new A.ah("\ud83d\udd11 \xab Le je\xfbne est la cl\xe9 de la cuisine de la Nature. \xbb \u2014 Arnold Ehret",B.bq,"Arnold Ehret",B.o,null)
B.ax2=new A.ah("\ud83d\udeab \xab La question n'est pas ce qu'il faut manger, mais ce qu'il ne faut PAS manger. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.awo=new A.ah("\ud83e\uddea \xab La th\xe9orie des prot\xe9ines est la doctrine la plus dangereuse jamais enseign\xe9e. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.awp=new A.ah("\u2728 \xab Un corps propre vit avec une quantit\xe9 infime de nourriture. \xbb \u2014 Arnold Ehret",B.a3,"Arnold Ehret",B.o,null)
B.avI=new A.ah("\ud83d\ude91 \xab Plus de gens ont \xe9t\xe9 l\xe9s\xe9s par une mauvaise reprise alimentaire que par le je\xfbne lui-m\xeame. \xbb \u2014 Arnold Ehret",B.dr,"Arnold Ehret",B.o,null)
B.awa=new A.ah("\ud83d\udd2d \xab Tout ce qui n'est pas simple et facile \xe0 comprendre ne peut \xeatre la v\xe9rit\xe9. \xbb \u2014 Arnold Ehret",B.cq,"Arnold Ehret",B.o,null)
B.avr=new A.ah("\ud83e\uddf9 \xab Mon syst\xe8me n'est pas un rem\xe8de \u2014 c'est une r\xe9g\xe9n\xe9ration, un grand m\xe9nage int\xe9rieur. \xbb \u2014 Arnold Ehret",B.bq,"Arnold Ehret",B.o,null)
B.avM=new A.ah("\ud83d\uded1 \xab Plus l'homme accumule de d\xe9chets, plus il doit manger pour stopper l'\xe9limination. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.avJ=new A.ah("\u2600\ufe0f \xab L'air et le soleil sont les plus grands alli\xe9s du corps. \xbb \u2014 Arnold Ehret",B.bj,"Arnold Ehret",B.o,null)
B.av5=new A.ah('\ud83e\udd12 \xab Ce que l\'humain moyen appelle \\"sant\xe9\\" est en r\xe9alit\xe9 un \xe9tat de maladie latente. \xbb \u2014 Arnold Ehret',B.cq,"Arnold Ehret",B.o,null)
B.aw3=new A.ah("\ud83c\udf7d\ufe0f \xab 99,99% de toutes les maladies trouvent leur cause dans l'alimentation. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.awD=new A.ah("\ud83d\udd04 \xab Chaque maladie est un effort du corps pour \xe9liminer les d\xe9chets, le mucus et les toxines. \xbb \u2014 Arnold Ehret",B.a3,"Arnold Ehret",B.o,null)
B.awX=new A.ah("\ud83c\udfe5 \xab Ce n'est pas la maladie qu'il faut gu\xe9rir, c'est le CORPS \u2014 il doit \xeatre nettoy\xe9. \xbb \u2014 Arnold Ehret",B.br,"Arnold Ehret",B.o,null)
B.avA=new A.ah("\u26a1 \xab La vitalit\xe9 ne d\xe9pend pas directement de la nourriture. V = P \u2212 O. \xbb \u2014 Arnold Ehret",B.bq,"Arnold Ehret",B.o,null)
B.awY=new A.ah("\ud83d\udc80 \xab Les je\xfbneurs qui sont morts n'ont pas succomb\xe9 au manque de nourriture, mais \xe9touff\xe9s dans leurs propres d\xe9chets. \xbb \u2014 Arnold Ehret",B.dr,"Arnold Ehret",B.o,null)
B.awK=new A.ah("\ud83c\udf3f \xab La nature ne fournit pas d'aliment qui doive \xeatre pr\xe9par\xe9 par l'homme pour \xeatre mang\xe9. \xbb \u2014 Arnold Ehret",B.a3,"Arnold Ehret",B.o,null)
B.avK=new A.ah("\ud83c\udf05 \xab Mange ton chemin vers le Paradis \u2014 physiquement. \xbb \u2014 Arnold Ehret",B.bj,"Arnold Ehret",B.o,null)
B.av7=new A.ah("\ud83c\udf04 \xab Le pire de toutes les habitudes alimentaires est le petit-d\xe9jeuner copieux. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.aw6=new A.ah("\ud83d\udc45 \xab La langue est le miroir de tout le syst\xe8me membranaire. \xbb \u2014 Arnold Ehret",B.cq,"Arnold Ehret",B.o,null)
B.avz=new A.ah("\ud83d\udeab \xab On ne peut pas gu\xe9rir sans arr\xeater de manger les aliments qui produisent la maladie. \xbb \u2014 Arnold Ehret",B.aE,"Arnold Ehret",B.o,null)
B.xV=s([B.avn,B.avu,B.avL,B.avp,B.aw4,B.avb,B.awE,B.avP,B.ax0,B.awi,B.awU,B.aw0,B.awP,B.avB,B.ax3,B.awT,B.awM,B.avX,B.ax2,B.awo,B.awp,B.avI,B.awa,B.avr,B.avM,B.avJ,B.av5,B.aw3,B.awD,B.awX,B.avA,B.awY,B.awK,B.avK,B.av7,B.aw6,B.avz],t.pb)
B.a2i=s(["Le je\xfbne active la filtration r\xe9nale et le drainage lymphatique. \u2014 Dr. Morse","Bounce sur un rebounder chaque jour. C'est le meilleur exercice lymphatique. \u2014 Morse","Les fruits sont vos nettoyeurs, les l\xe9gumes vos b\xe2tisseurs. \u2014 Dr. Morse","Sans surr\xe9nales fortes, pas de filtration. Sans filtration, pas de gu\xe9rison. \u2014 Morse","Donnez-vous le temps de gu\xe9rir. Rome ne s'est pas construite en un jour. \u2014 Morse"],t.s)
B.a2j=s(["-//w3c//dtd xhtml 1.0 frameset//","-//w3c//dtd xhtml 1.0 transitional//"],t.s)
B.a2k=s(["pre","listing","textarea"],t.s)
B.Rb=new A.eL(2,"D\xe9but du je\xfbne ! Comment te sens-tu ?","Ehret : La digestion du dernier repas s'ach\xe8ve. Le nettoyage interne commence doucement.","\ud83c\udf3f",B.hb)
B.Ra=new A.eL(6,"6h ! L'obstruction diminue. Tout va bien ?","Ehret : V = P \u2212 O. Moins d'obstruction signifie plus de vitalit\xe9. Tu progresses.","\u26a1",B.hb)
B.R5=new A.eL(12,"\ud83d\udd25 C\xe9tose ! Ton corps br\xfble les r\xe9serves. Des sensations ?","Ehret : Le corps br\xfble les graisses charg\xe9es de mucus. Nettoyage m\xe9tabolique en cours.","\ud83d\udd25",B.hc)
B.Rp=new A.eL(18,"18h ! Le m\xe9decin int\xe9rieur op\xe8re. Comment \xe7a va ?","Ehret : Les inconforts sont des signes de nettoyage. Le mucus ancien se dissout.","\ud83e\ude7a",B.hc)
B.Rc=new A.eL(24,"\u267b\ufe0f 24h ! Autophagie active. Ton \xe9tat ?","Ehret : L'autophagie recycle les prot\xe9ines endommag\xe9es. Le je\xfbne rationnel porte ses fruits.","\u267b\ufe0f",B.dM)
B.Rd=new A.eL(36,"36h ! Clart\xe9 mentale extraordinaire ?","Ehret : Le je\xfbne avanc\xe9 apporte une clart\xe9 mentale que tu ne trouveras jamais dans la nourriture.","\ud83e\udde0",B.dM)
B.Rm=new A.eL(48,"48h ! R\xe9g\xe9n\xe9ration profonde. Comment te sens-tu ?","Ehret : L'homme sain ne se fatigue pas \u2014 il est mouvement perp\xe9tuel. Tu r\xe9g\xe9n\xe8res en profondeur.","\ud83c\udf1f",B.dM)
